    internal static int DtFillRandom(emon.Port.Cells c, int n, long seed) {
        // n splitmix bytes: incompressible.
        emon.Port.Cells st = emon.Port.NewCells();
        int i = 0;
        Splitmix.SmSeed(st, seed);
        emon.Port.CellsDrop(c, 0);
        while (i < n) {
            emon.Port.CellsPush(c, Splitmix.SmBelow(st, 256));
            i += 1;
        }
        return n;
    }
    internal static int DtLetter(int word, int k) {
        return 97 + ((Splitmix.SmLo(Splitmix.SmAt(777, (word * 16) + k)) & 2147483647) % 26);
    }
    internal static int DtFillText(emon.Port.Cells c, int n, long seed) {
        // n bytes of pseudo-text: words from a vocabulary of 48, 2..9 letters,
        // a space after each and a newline after about every twelfth.
        emon.Port.Cells st = emon.Port.NewCells();
        int w = 0;
        int k = 0;
        int cnt = 0;
        Splitmix.SmSeed(st, seed);
        emon.Port.CellsDrop(c, 0);
        while (emon.Port.CellsLen(c) < n) {
            w = Splitmix.SmBelow(st, 48);
            k = 0;
            while (k < (2 + (w % 8))) {
                emon.Port.CellsPush(c, DtLetter(w, k));
                k += 1;
            }
            cnt += 1;
            if ((cnt % 12) == 0) {
                emon.Port.CellsPush(c, 10);
            } else {
                emon.Port.CellsPush(c, 32);
            }
        }
        emon.Port.CellsDrop(c, n);
        return n;
    }
    internal static int DtFillRepeat(emon.Port.Cells c, int n, int a, int b, int d) {
        // n bytes of a, b, d repeated.
        int i = 0;
        emon.Port.CellsDrop(c, 0);
        while (i < n) {
            emon.Port.CellsPush(c, a);
            emon.Port.CellsPush(c, b);
            emon.Port.CellsPush(c, d);
            i += 3;
        }
        emon.Port.CellsDrop(c, n);
        return n;
    }
    internal static int DtCompress(emon.Port.Cells ws, emon.Port.Buf z, emon.Port.Cells src, int n, int mode) {
        // src[0, n) in one write, in block mode `mode`; the stream's length.
        Deflate.DfInit(ws);
        Deflate.DfForce(ws, mode);
        emon.Port.BufTruncate(z, 0);
        Deflate.DfWriteCells(ws, z, src, 0, n);
        Deflate.DfFinish(ws, z);
        return emon.Port.BufLen(z);
    }
    internal static int DtVerify(emon.Port.Buf z, emon.Port.Cells src, int n, emon.Port.Cells dec, emon.Port.Cells st) {
        // -1 when z inflates (header and Adler-32 checked) to exactly src[0, n);
        // -2 for a wrong length; i for the first differing byte; -10 - status
        // when inflate refuses it.
        emon.Port.CellsDrop(dec, 0);
        int rc = Inflate.IzZlib(emon.Port.BufBlob(z), 0, emon.Port.BufLen(z), dec, st);
        int i = 0;
        if (rc != Inflate.IzOk()) {
            return 0 - (rc + 10);
        }
        if (emon.Port.CellsLen(dec) != n) {
            return -2;
        }
        while (i < n) {
            if (emon.Port.CellsAt(dec, i) != emon.Port.CellsAt(src, i)) {
                return i;
            }
            i += 1;
        }
        return -1;
    }
    internal static int DtSame(emon.Port.Buf a, emon.Port.Buf b) {
        // 1 when the two buffers hold the same bytes.
        int i = 0;
        if (emon.Port.BufLen(a) != emon.Port.BufLen(b)) {
            return 0;
        }
        while (i < emon.Port.BufLen(a)) {
            if (emon.Port.BufAt(a, i) != emon.Port.BufAt(b, i)) {
                return 0;
            }
            i += 1;
        }
        return 1;
    }
    internal static int DtTrip(emon.Port.Cells src, int n, int mode) {
        // Compress and verify with fresh state; -1 is a pass.
        emon.Port.Cells ws = emon.Port.NewCells();
        emon.Port.Buf z = emon.Port.NewBuf();
        emon.Port.Cells dec = emon.Port.NewCells();
        emon.Port.Cells st = emon.Port.NewCells();
        DtCompress(ws, z, src, n, mode);
        return DtVerify(z, src, n, dec, st);
    }
    [Xunit.Fact]
    public static void TestEmptyInputIsTheFixedEmptyBlock() {
        emon.Port.Cells ws = emon.Port.NewCells();
        emon.Port.Buf z = emon.Port.NewBuf();
        Deflate.DfInit(ws);
        Deflate.DfFinish(ws, z);
        emon.Testport.AssertEq(emon.Port.BufLen(z), 8, "eight bytes");
        emon.Testport.AssertEq(emon.Port.BufAt(z, 0), 120, "CMF");
        emon.Testport.AssertEq(emon.Port.BufAt(z, 1), 1, "FLG");
        emon.Testport.AssertEq(emon.Port.BufAt(z, 2), 3, "final fixed block, end-of-block");
        emon.Testport.AssertEq(emon.Port.BufAt(z, 3), 0, "end-of-block, last bits");
        emon.Testport.AssertEq(emon.Port.BufAt(z, 4), 0, "Adler-32 of nothing: 00");
        emon.Testport.AssertEq(emon.Port.BufAt(z, 5), 0, "00");
        emon.Testport.AssertEq(emon.Port.BufAt(z, 6), 0, "00");
        emon.Testport.AssertEq(emon.Port.BufAt(z, 7), 1, "01");
    }
