        emon.Testport.AssertEq(emon.Port.BufAt(z, 4), 0, "00");
        emon.Testport.AssertEq(emon.Port.BufAt(z, 5), 0, "00");
        emon.Testport.AssertEq(emon.Port.BufAt(z, 6), 98, "62");
        emon.Testport.AssertEq(emon.Port.BufAt(z, 7), 0, "00");
