    [Xunit.Fact]
    public static void TestTheOutputDoesNotDependOnHowTheInputIsSplit() {
        emon.Port.Cells src = emon.Port.NewCells();
        emon.Port.Cells ws = emon.Port.NewCells();
        emon.Port.Buf whole = emon.Port.NewBuf();
        emon.Port.Buf bytewise = emon.Port.NewBuf();
        emon.Port.Buf chunks = emon.Port.NewBuf();
        int i = 0;
        DtFillText(src, 70000, 13);
        DtCompress(ws, whole, src, 70000, 0);
        Deflate.DfInit(ws);
        while (i < 70000) {
            Deflate.DfWriteCells(ws, bytewise, src, i, i + 1);
            i += 1;
        }
        Deflate.DfFinish(ws, bytewise);
        Deflate.DfInit(ws);
        i = 0;
        while (i < 70000) {
            Deflate.DfWriteCells(ws, chunks, src, i, i + 1000);
            i += 1000;
        }
        Deflate.DfFinish(ws, chunks);
        emon.Testport.AssertEq(DtSame(whole, bytewise), 1, "byte by byte");
        emon.Testport.AssertEq(DtSame(whole, chunks), 1, "in chunks of 1000");
    }
